document.addEventListener("DOMContentLoaded",()=>{const t=document.getElementById("cost-comparison");if(!t)return;const n=document.getElementById("comparison-error"),r=document.getElementById("comparison-results"),m=Array.from(t.querySelectorAll('input[type="number"]'));t.addEventListener("submit",f=>{f.preventDefault(),n.hidden=!0;let a;for(const e of m){const u=Number(e.value),c=e.value.trim()!==""&&e.validity.valid&&Number.isFinite(u)&&u>=0;e.setAttribute("aria-invalid",String(!c)),!c&&!a&&(a=e)}if(a){r.hidden=!0,n.textContent="Enter a non-negative number in each field. Use zero where there is no cost.",n.hidden=!1,a.focus();return}const o=e=>Number(document.getElementById(e).value),i=o("internal-hours")*o("internal-rate"),d=o("external-hours")*o("external-rate")+o("external-extra");if(!Number.isFinite(i)||!Number.isFinite(d)){r.hidden=!0,n.textContent="Those figures are too large to compare. Check the hours and rates.",n.hidden=!1;return}const h=document.getElementById("comparison-currency").value,l=new Intl.NumberFormat("en",{style:"currency",currency:h,maximumFractionDigits:2});document.getElementById("internal-total").textContent=l.format(i),document.getElementById("external-total").textContent=l.format(d);const s=i-d;document.getElementById("comparison-label").textContent=s>0?"External budget is lower by":s<0?"External budget is higher by":"Both budgets are equal",document.getElementById("comparison-difference").textContent=l.format(Math.abs(s)),r.hidden=!1}),t.addEventListener("input",()=>{r.hidden=!0}),t.addEventListener("change",()=>{r.hidden=!0})});
